/// <summary>How hard losing the race to space hits you. Chosen on the setup screen.</summary>
public sealed record SpaceRaceDef(string Id, string Name, string Desc, bool DefeatIfBeaten, string[] RivalLeadModifiers, string[] PlayerFirstModifiers);

/// <summary>Civ VI's difficulty levels (Act 1): rivals' yields are multiplied. Act 2 has its own AI difficulty (galaxy_difficulties).</summary>
public sealed record DifficultyDef(string Id, string NameLoc, string Name, double AiYieldMult, string Desc);

/// <summary>Act 1 map sizes, with the default number of rivals and of Stellaris alien empires that join in Act 2.</summary>
public sealed record MapSizeDef(string Id, string Name, int Width, int Height, int DefaultRivals, int MaxRivals, int NaturalWonders, int Aliens, string Desc);

/// <summary>How long Act 2 runs before the highest score wins. Each turn is act2_months_per_turn months.</summary>
public sealed record GameLengthDef(string Id, string Name, int EndYear, string Desc);

/// <summary>Act 1 yields. Civ VI's culture and faith are folded in: culture counts as science, faith as gold.</summary>
public sealed record YieldDef(string Id, string NameLoc, string Name, string Icon, string Color, string Desc);

/// <summary>Act 1 terrain. Yields are Civ VI's (Terrain_YieldChanges); mountains can't be worked or settled. ground/ground_fow: Civ VI terrain textures for seen and fogged land (none on water, which is drawn in its colour); overlay: Civ VI strategic-view sprite drawn on top ({n} picks a variant; none for flat land).</summary>
public sealed record TerrainDef(string Id, string NameLoc, int Food, int Production, int Gold, int Science, bool Land, bool Passable, string Icon, string Color, string Ground, string GroundFow, string Overlay, string OverlayFow);

/// <summary>Act 1 features on land tiles. Yields add to the terrain's (Civ VI's Feature_YieldChanges). sprite/sprite_fow: Civ VI strategic-view picture when seen / in fog.</summary>
public sealed record FeatureDef(string Id, string NameLoc, string[] Terrains, int Food, int Production, int Gold, int Science, double Density, string Icon, string Sprite, string SpriteFow);

/// <summary>Natural wonders on the Act 1 map. Their tile yields come from Civ VI (culture as science, faith as gold). In Act 2 each becomes a rare star system: whoever reached space first starts owning it, and whoever holds it gets the modifier. DEFAULT covers natural wonders not listed. sprite: Civ VI strategic-view picture (none: its icon is shown).</summary>
public sealed record NaturalWonderDef(string Id, bool Land, int Food, int Production, int Gold, int Science, string Modifier, string Sprite, string Desc);

/// <summary>Act 1 city buildings: real Civ VI buildings (name, icon and cost from the install), with simplified effects. Cost here is Civ VI's, before act1_build_cost_mult. district: the Civ VI district it stands in (shown on a tile next to the city; none: the city centre); sprite: its strategic-view picture.</summary>
public sealed record BuildingDef(string Id, string RequiresTech, string RequiresBuilding, bool Coastal, int Cost, int Food, int Production, int Gold, int Science, int FoodPct, int ProductionPct, int GoldPct, int SciencePct, string District, string Sprite, string Desc);

/// <summary>Act 1 world wonders: only one civilization can build each. Name, icon and cost come from Civ VI; wonders Civ VI unlocks with a civic are unlocked by the tech listed here. In Act 2 each wonder you built becomes a feature on your homeworld with its modifier. sprite: its Civ VI strategic-view picture, shown on its own tile next to the city.</summary>
public sealed record WonderDef(string Id, string RequiresTech, int Cost, string Scope, int Food, int Production, int Gold, int Science, int FoodPct, int ProductionPct, int GoldPct, int SciencePct, string Modifier, string Sprite, string Desc);

/// <summary>Act 1 space projects (Civ VI's), built in a city with a Spaceport. Cost is Civ VI's, before act1_build_cost_mult.</summary>
public sealed record ProjectDef(string Id, string RequiresTech, string RequiresBuilding, int Cost, string Kind, string Desc);

/// <summary>Act 1 land units, stone age to space age. Strength, cost, moves, upkeep, tech, resource and upgrade are read from the player's Civ VI (Units, UnitUpgrades); the numbers here are the base game's, used only if the install lacks a value. 'line' sets the role the AI gives it and what it upgrades along.</summary>
public sealed record UnitDef(string Id, string Line, int Combat, int Ranged, int Range, int Moves, int Cost, int Maintenance, string PrereqTech, string Resource, string Upgrade, bool Siege);

/// <summary>Act 1 tile improvements a Builder makes (Civ VI's: name, icon and picture from the install). A tile takes one improvement. terrains/features: where it can go; resources: resources it works (any terrain). A tile with woods, rainforest or marsh only takes improvements that list that feature or work its resource.</summary>
public sealed record ImprovementDef(string Id, string NameLoc, string Icon, string PrereqTech, int Food, int Production, int Gold, int Science, string[] Terrains, string[] Features, string[] Resources, string Sprite);

/// <summary>Each civilization's trait, helping in both acts. Its title in game is the civilization's own Civ VI ability name (from the install); these are the effects. Act 1: % to city yields, unit strength and costs, Builder charges, opinion with other civs. Act 2: modifiers.</summary>
public sealed record CivTraitDef(string Id, string Name, int FoodPct, int ProductionPct, int GoldPct, int SciencePct, int WonderPct, int UnitStrength, int UnitCostPct, int SettlerCostPct, int BuilderCharges, int Opinion, bool EmbarkEarly, string[] Act2Modifiers, string Desc);

/// <summary>Which trait each civilization has (civilizations not listed get one picked from their name).</summary>
public sealed record CivTraitMapDef(string Id, string Trait);

/// <summary>Out-of-this-world sites (Stellaris's deposits), a few per game. Act 1: on the map like natural wonders; the tile yields these and, held with some neighbouring tiles, gives act1_stat empire-wide; holding it at the handoff lets that empire research unlock_tech. Act 2: a few planets carry one; holding the system gives act2_modifier and lets you research unlock_tech.</summary>
public sealed record ExoticSiteDef(string Id, string Name, string Art, string Icon, bool Land, int Food, int Production, int Gold, int Science, string Act1Stat, int Act1Value, string Act2Modifier, string UnlockTech, string Desc);

/// <summary>Act 1's pre-FTL research (Stellaris's starting technologies): researched like Civ VI techs once their prerequisites are known. 'core' ones are needed for the Moon Landing; every one you have becomes a known technology in Act 2 (the rest can be researched there).</summary>
public sealed record PreftlTechDef(string Id, string Area, string[] Requires, int Cost, bool Core);

/// <summary>Civ VI techs that carry a Space Age legacy: each one you research gives its modifier at the start of Act 2. The tech's tooltip names it.</summary>
public sealed record TechLegacyDef(string CivTech, string Title, string Modifier);

/// <summary>Act 1 calendar: the year follows the most advanced civilization's progress through Civ VI's eras, so the space age arrives in the 20th century however fast the game goes. city_sprite: how cities look in that era (Civ VI strategic view; {v} is Visible or Revealed).</summary>
public sealed record EraDef(string Id, int StartYear, string CitySprite);

/// <summary>Act 2 resources (Stellaris's). Research is one pool here.</summary>
public sealed record ResourceDef(string Id, string NameLoc, string Name, string Art, int Start, string Desc);

/// <summary>Act 2 star classes (Stellaris's).</summary>
public sealed record StarClassDef(string Id, string NameLoc, int Weight, string Art, string Color);

/// <summary>Act 2 planet classes (Stellaris's; icon and name from the install). Habitable planets can be colonized; the rest only count for the system.</summary>
public sealed record PlanetClassDef(string Id, bool Habitable, int Weight, int SizeMin, int SizeMax);

/// <summary>Act 2 planet districts (Stellaris's). Each gives act2_district_jobs jobs; a planet has room for one district per 3 sizes.</summary>
public sealed record DistrictDef(string Id, string NameLoc, string Resource, int PerJob, int CostMinerals, string Art, string Desc);

/// <summary>Act 2 planet buildings (Stellaris's). One slot per act2_building_slots_per_pops pops, plus one.</summary>
public sealed record PlanetBuildingDef(string Id, string NameLoc, string RequiresTech, string Resource, int Jobs, int PerJob, int CostMinerals, int UpkeepEnergy, string Art, string Desc);

/// <summary>Act 2 ships (Stellaris's hulls). Power is combat damage per month; hull is how much damage it takes; speed is hyperlane distance per month.</summary>
public sealed record ShipDef(string Id, string NameLoc, string Role, int CostAlloys, int CostMinerals, int CostFood, int BuildMonths, int Power, int Hull, int Speed, int NavalCap, int UpkeepEnergy, string RequiresTech, string Art);

