public sealed record Act2TechDef(string Id, string NameLoc, int Tier, string Area, int Cost, string[] Requires, string[] Modifiers, string Unlocks, string Feature, string Art);

/// <summary>Act 2 galaxy size: star systems per empire (every empire gets one identical spiral arm of this many systems).</summary>
public sealed record GalaxySizeDef(string Id, string Name, int SystemsPerEmpire, string Desc);

/// <summary>Act 2 AI difficulty (Stellaris's names). Every AI empire's output is multiplied by ai_mult; aggression scales how readily they declare war.</summary>
public sealed record GalaxyDifficultyDef(string Id, string Name, double AiMult, double Aggression, string Desc);

/// <summary>Every Act 2 bonus: legacy techs, wonders, rare systems, the space race and Act 2 techs. stat is one the game understands (see game_systems).</summary>
public sealed record ModifierDef(string Id, string Stat, double Value, string Name, string EffectText);

/// <summary>Stellaris's own empires in Act 2: read from the player's prescripted empires (not human, not machine). aggression is how readily the AI goes to war.</summary>
public sealed record AlienDef(string Id, double Aggression, string Desc);

/// <summary>Every picture, font and sound the game uses, and where it comes from in the player's own installs. Civ VI icons (ICON_*) and leader pictures are looked up by name and need no row here.</summary>
public sealed record AssetRefDef(string Id, string Game, string Kind, string[] Lookup, string UsedBy, bool Verified, string Note);

/// <summary>What comes from each game and how it is read.</summary>
public sealed record GameSystemDef(string Id, string Game, string What, string Source, string Impl, bool Verified);

